p=argparse.ArgumentParser();p.add_argument('before');p.add_argument('after');p.add_argument('routing_root');p.add_argument('prefix');p.add_argument('output');args=p.parse_args();study=Path(__file__).resolve().parents[1];root=Path(args.routing_root)
