 row={**{k:a[k] for k in ['a','pa','b','pb']},'category':cat,'limit_mm':a['limit'],'before_mm':a['distance_l1_mm'],'after_mm':z['distance_l1_mm'],'before_pass':a['pass'],'after_pass':z['pass']};rows.append(row)
